class SalesInvoiceData extends DataClass
    implements Insertable<SalesInvoiceData> {
  final int id;
  final String createdAt;
  final String modifiedAt;
  final String? name;

  /// assigned on Submit
  final int docstatus;
  final String status;
  final String postingDatetime;
  final int posProfileId;
  final int posOpeningEntryId;
  final int isReturn;
  final int? returnAgainstId;
  final int updateStock;
  final int setWarehouseId;
  final int priceListId;
  final int? taxesTemplateId;
  final double totalQty;
  final double total;

  /// sum of item amounts
  final double netTotal;

  /// sum of item net amounts
  final String applyDiscountOn;
  final double additionalDiscountPercentage;
  final double discountAmount;
  final double totalTaxesAndCharges;
  final double grandTotal;
  final double roundingAdjustment;
  final double roundedTotal;
  final String? inWords;
  final double paidAmount;
  final double changeAmount;
  final int? letterHeadId;
  final int? printHeadingId;
  final int? tcId;
  final String? terms;

  /// Terms and Conditions Details, copied text
  final String? remarks;
  const SalesInvoiceData({
    required this.id,
    required this.createdAt,
    required this.modifiedAt,
    this.name,
    required this.docstatus,
    required this.status,
    required this.postingDatetime,
    required this.posProfileId,
    required this.posOpeningEntryId,
    required this.isReturn,
    this.returnAgainstId,
    required this.updateStock,
    required this.setWarehouseId,
    required this.priceListId,
    this.taxesTemplateId,
    required this.totalQty,
    required this.total,
    required this.netTotal,
    required this.applyDiscountOn,
    required this.additionalDiscountPercentage,
    required this.discountAmount,
    required this.totalTaxesAndCharges,
    required this.grandTotal,
    required this.roundingAdjustment,
    required this.roundedTotal,
    this.inWords,
    required this.paidAmount,
    required this.changeAmount,
    this.letterHeadId,
    this.printHeadingId,
    this.tcId,
    this.terms,
    this.remarks,
  });
  @override
