class BrandData extends DataClass implements Insertable<BrandData> {
  final int id;
  final String createdAt;
  final String modifiedAt;
  final String name;
  final String? description;
  const BrandData({
    required this.id,
    required this.createdAt,
    required this.modifiedAt,
    required this.name,
    this.description,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['created_at'] = Variable<String>(createdAt);
    map['modified_at'] = Variable<String>(modifiedAt);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    return map;
  }

  BrandCompanion toCompanion(bool nullToAbsent) {
    return BrandCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      modifiedAt: Value(modifiedAt),
      name: Value(name),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
    );
  }

  factory BrandData.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return BrandData(
      id: serializer.fromJson<int>(json['id']),
      createdAt: serializer.fromJson<String>(json['created_at']),
      modifiedAt: serializer.fromJson<String>(json['modified_at']),
      name: serializer.fromJson<String>(json['name']),
      description: serializer.fromJson<String?>(json['description']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'created_at': serializer.toJson<String>(createdAt),
      'modified_at': serializer.toJson<String>(modifiedAt),
      'name': serializer.toJson<String>(name),
      'description': serializer.toJson<String?>(description),
    };
  }

  BrandData copyWith({
    int? id,
    String? createdAt,
    String? modifiedAt,
    String? name,
    Value<String?> description = const Value.absent(),
  }) => BrandData(
    id: id ?? this.id,
    createdAt: createdAt ?? this.createdAt,
    modifiedAt: modifiedAt ?? this.modifiedAt,
    name: name ?? this.name,
    description: description.present ? description.value : this.description,
  );
  BrandData copyWithCompanion(BrandCompanion data) {
    return BrandData(
      id: data.id.present ? data.id.value : this.id,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      modifiedAt: data.modifiedAt.present
          ? data.modifiedAt.value
          : this.modifiedAt,
      name: data.name.present ? data.name.value : this.name,
      description: data.description.present
          ? data.description.value
          : this.description,
    );
  }

  @override
  String toString() {
    return (StringBuffer('BrandData(')
          ..write('id: $id, ')
          ..write('createdAt: $createdAt, ')
          ..write('modifiedAt: $modifiedAt, ')
          ..write('name: $name, ')
          ..write('description: $description')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(id, createdAt, modifiedAt, name, description);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
