class ItemData extends DataClass implements Insertable<ItemData> {
  final int id;
  final String createdAt;
  final String modifiedAt;
  final String itemCode;
  final String itemName;
  final int itemGroupId;
  final int stockUomId;

  /// Default Unit of Measure
  final int disabled;
  final int isStockItem;

  /// Maintain Stock
  final int isSalesItem;
  final String? description;
  final Uint8List? image;

  /// JPEG, longest side 512px
  final int? brandId;
  final double standardRate;

  /// Standard Selling Rate, used on create
  final double valuationRate;

  /// fallback cost when the ledger has none
  final String? valuationMethod;

  /// NULL = setting
  final int allowNegativeStock;
  final int? shelfLifeInDays;
  final String? endOfLife;
  final int? warrantyPeriod;

  /// days
  final int? salesUomId;
  final double maxDiscount;
  final int? defaultWarehouseId;
  final int hasVariants;
  final int? variantOfId;
  final int hasBatchNo;
  final int createNewBatch;

  /// Automatically Create New Batch
  final String? batchNumberSeries;
  final int hasExpiryDate;
  final int hasSerialNo;
  final String? serialNoSeries;
  const ItemData({
    required this.id,
    required this.createdAt,
    required this.modifiedAt,
    required this.itemCode,
    required this.itemName,
    required this.itemGroupId,
    required this.stockUomId,
    required this.disabled,
    required this.isStockItem,
    required this.isSalesItem,
    this.description,
    this.image,
    this.brandId,
    required this.standardRate,
    required this.valuationRate,
    this.valuationMethod,
    required this.allowNegativeStock,
    this.shelfLifeInDays,
    this.endOfLife,
    this.warrantyPeriod,
    this.salesUomId,
    required this.maxDiscount,
    this.defaultWarehouseId,
    required this.hasVariants,
    this.variantOfId,
    required this.hasBatchNo,
    required this.createNewBatch,
    this.batchNumberSeries,
    required this.hasExpiryDate,
    required this.hasSerialNo,
    this.serialNoSeries,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['created_at'] = Variable<String>(createdAt);
    map['modified_at'] = Variable<String>(modifiedAt);
    map['item_code'] = Variable<String>(itemCode);
    map['item_name'] = Variable<String>(itemName);
    map['item_group_id'] = Variable<int>(itemGroupId);
    map['stock_uom_id'] = Variable<int>(stockUomId);
    map['disabled'] = Variable<int>(disabled);
    map['is_stock_item'] = Variable<int>(isStockItem);
    map['is_sales_item'] = Variable<int>(isSalesItem);
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    if (!nullToAbsent || image != null) {
      map['image'] = Variable<Uint8List>(image);
    }
    if (!nullToAbsent || brandId != null) {
      map['brand_id'] = Variable<int>(brandId);
    }
    map['standard_rate'] = Variable<double>(standardRate);
    map['valuation_rate'] = Variable<double>(valuationRate);
    if (!nullToAbsent || valuationMethod != null) {
      map['valuation_method'] = Variable<String>(valuationMethod);
    }
    map['allow_negative_stock'] = Variable<int>(allowNegativeStock);
    if (!nullToAbsent || shelfLifeInDays != null) {
      map['shelf_life_in_days'] = Variable<int>(shelfLifeInDays);
    }
    if (!nullToAbsent || endOfLife != null) {
      map['end_of_life'] = Variable<String>(endOfLife);
    }
    if (!nullToAbsent || warrantyPeriod != null) {
      map['warranty_period'] = Variable<int>(warrantyPeriod);
    }
    if (!nullToAbsent || salesUomId != null) {
      map['sales_uom_id'] = Variable<int>(salesUomId);
    }
    map['max_discount'] = Variable<double>(maxDiscount);
    if (!nullToAbsent || defaultWarehouseId != null) {
      map['default_warehouse_id'] = Variable<int>(defaultWarehouseId);
    }
    map['has_variants'] = Variable<int>(hasVariants);
    if (!nullToAbsent || variantOfId != null) {
      map['variant_of_id'] = Variable<int>(variantOfId);
    }
    map['has_batch_no'] = Variable<int>(hasBatchNo);
    map['create_new_batch'] = Variable<int>(createNewBatch);
    if (!nullToAbsent || batchNumberSeries != null) {
      map['batch_number_series'] = Variable<String>(batchNumberSeries);
    }
    map['has_expiry_date'] = Variable<int>(hasExpiryDate);
    map['has_serial_no'] = Variable<int>(hasSerialNo);
    if (!nullToAbsent || serialNoSeries != null) {
      map['serial_no_series'] = Variable<String>(serialNoSeries);
    }
    return map;
  }

  ItemCompanion toCompanion(bool nullToAbsent) {
    return ItemCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      modifiedAt: Value(modifiedAt),
      itemCode: Value(itemCode),
      itemName: Value(itemName),
