          : Value(defaultWarehouseId),
      hasVariants: Value(hasVariants),
      variantOfId: variantOfId == null && nullToAbsent
          ? const Value.absent()
          : Value(variantOfId),
      hasBatchNo: Value(hasBatchNo),
      createNewBatch: Value(createNewBatch),
      batchNumberSeries: batchNumberSeries == null && nullToAbsent
          ? const Value.absent()
          : Value(batchNumberSeries),
      hasExpiryDate: Value(hasExpiryDate),
      hasSerialNo: Value(hasSerialNo),
      serialNoSeries: serialNoSeries == null && nullToAbsent
          ? const Value.absent()
          : Value(serialNoSeries),
    );
