                return PrefetchHooks(
                  db: db,
                  explicitlyWatchedTables: [
                    if (itemRefs) db.item,
                    if (posProfileItemGroupRefs) db.posProfileItemGroup,
                  ],
                  addJoins:
                      <
                        T extends TableManagerState<
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
                          dynamic,
